css:
.qr-sim-container {
  padding: 28px;
  background: linear-gradient(180deg, #fdf6ec 0%, #f7ede0 100%);
  min-height: 100vh;
  font-family: 'Inter', -apple-system, 'Segoe UI', sans-serif;
  color: #2a1f14;
}
.qr-sim-container .qr-sim-header {
  background: linear-gradient(135deg, #c1272d 0%, #fcd116 55%, #003893 100%);
  color: #fff;
  border-radius: 18px;
  padding: 28px 32px;
  margin-bottom: 22px;
  box-shadow: 0 10px 28px rgba(193,39,45,0.18);
}
.qr-sim-container .qr-sim-badge {
  display: inline-block;
  background: rgba(255,255,255,0.18);
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.qr-sim-container .qr-sim-header h1 {
  font-size: 1.7rem;
  font-weight: 800;
  margin: 0 0 6px 0;
}
.qr-sim-container .qr-sim-subtitle {
  font-size: 0.95rem;
  opacity: 0.92;
}
.qr-sim-container .qr-sim-meta-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  gap: 16px;
  flex-wrap: wrap;
}
.qr-sim-container .qr-sim-period-counter {
  background: #2a1f14;
  color: #fcd116;
  padding: 10px 18px;
  border-radius: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.qr-sim-container .qr-sim-round-name {
  font-size: 1.05rem;
  font-weight: 700;
  color: #003893;
}
.qr-sim-container .qr-sim-briefing {
  background: #fff;
  border-left: 5px solid #003893;
  border-radius: 12px;
  padding: 18px 22px;
  margin-bottom: 22px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.05);
}
.qr-sim-container .qr-sim-briefing-head {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #6b5a3e;
  margin-bottom: 8px;
  font-weight: 700;
}
.qr-sim-container .qr-sim-briefing-text {
  font-size: 0.98rem;
  line-height: 1.55;
  color: #2a1f14;
}
.qr-sim-container .qr-sim-status-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 14px;
  margin-bottom: 22px;
}
.qr-sim-container .qr-sim-kpi-card {
  background: #fff;
  border-radius: 14px;
  padding: 18px 20px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.06);
  border-top: 4px solid #6b5a3e;
  transition: transform 0.2s ease;
}
.qr-sim-container .qr-sim-kpi-card:hover { transform: translateY(-3px); }
.qr-sim-container .qr-sim-kpi-credibility { border-top-color: #003893; }
.qr-sim-container .qr-sim-kpi-bias { border-top-color: #c1272d; }
.qr-sim-container .qr-sim-kpi-market { border-top-color: #2d6a4f; }
.qr-sim-container .qr-sim-kpi-budget { border-top-color: #fcd116; }
.qr-sim-container .qr-sim-kpi-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #6b5a3e;
  font-weight: 700;
  margin-bottom: 8px;
}
.qr-sim-container .qr-sim-kpi-value {
  font-size: 1.85rem;
  font-weight: 800;
  color: #2a1f14;
}
.qr-sim-container .qr-sim-controls {
  background: #fff;
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 22px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.06);
}
.qr-sim-container .qr-sim-controls h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: #003893;
  margin-bottom: 18px;
}
.qr-sim-container .qr-sim-field {
  margin-bottom: 16px;
}
.qr-sim-container .qr-sim-field label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  color: #2a1f14;
  margin-bottom: 6px;
}
.qr-sim-container .qr-sim-field select,
.qr-sim-container .qr-sim-field input[type="number"] {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid #d9c9a9;
  border-radius: 8px;
  background: #fdf6ec;
  font-size: 0.95rem;
  color: #2a1f14;
}
.qr-sim-container .qr-sim-field input[type="range"] {
  width: 100%;
  accent-color: #c1272d;
}
.qr-sim-container .qr-sim-range-value {
  font-size: 0.85rem;
  color: #6b5a3e;
  font-weight: 600;
  margin-top: 4px;
}
.qr-sim-container .qr-sim-actions {
  display: flex;
  gap: 10px;
  margin-top: 18px;
  flex-wrap: wrap;
}
.qr-sim-container .qr-sim-actions .btn-primary {
  background: #003893;
  border-color: #003893;
  font-weight: 700;
  padding: 10px 22px;
  border-radius: 8px;
}
.qr-sim-container .qr-sim-actions .btn-primary:hover {
  background: #002a70;
  border-color: #002a70;
}
.qr-sim-container .qr-sim-history {
  background: #fff;
  border-radius: 14px;
  padding: 20px;
  margin-bottom: 22px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.06);
}
.qr-sim-container .qr-sim-history h3 {
  font-size: 1rem;
  color: #003893;
  font-weight: 700;
  margin-bottom: 12px;
}
.qr-sim-container .qr-sim-history table {
  font-size: 0.88rem;
}
.qr-sim-container .qr-sim-chart-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 18px;
}
.qr-sim-container .qr-sim-chart {
  background: #fff;
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.06);
  height: 280px;
}
@media (max-width: 768px) {
  .qr-sim-container { padding: 16px; }
  .qr-sim-container .qr-sim-header { padding: 20px; }
  .qr-sim-container .qr-sim-header h1 { font-size: 1.3rem; }
  .qr-sim-container .qr-sim-kpi-value { font-size: 1.4rem; }
}

/* EQIL 2026-10-27: contrast, focus, motion, debrief (append-only, namespaced) */
.qr-sim-container .qr-sim-header {
  background: #003893;
  border-bottom: 6px solid #fcd116;
  box-shadow: 0 10px 28px rgba(0,56,147,0.18);
}
.qr-sim-container .qr-sim-badge { background: rgba(255,255,255,0.16); color: #fff; }
.qr-sim-container .qr-sim-subtitle { opacity: 1; color: #e8eefb; }
.qr-sim-container select, .qr-sim-container option { color-scheme: light; color: #2a1f14; background: #fdf6ec; }
.qr-sim-container :focus-visible { outline: 3px solid #003893; outline-offset: 2px; }
.qr-sim-container input[type="range"]:focus-visible { outline: 3px solid #003893; }
.qr-sim-container .qr-sim-history { overflow-x: auto; }
.qr-sim-container .qr-sim-chart { position: relative; min-height: 240px; }
.qr-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.qr-completion { padding: 8px 4px; text-align: left; }
.qr-completion .qr-cm-title { font-size: 1.05rem; font-weight: 700; color: #003893; margin-bottom: 12px; }
.qr-completion .qr-cm-rows { max-width: 520px; margin: 0 auto; }
.qr-completion .qr-cm-row { display: flex; justify-content: space-between; gap: 16px; padding: 6px 0; border-bottom: 1px solid #e6dcc8; }
.qr-completion .qr-cm-k { color: #5c4d33; }
.qr-completion .qr-cm-v { font-weight: 700; color: #2a1f14; }
.qr-completion .qr-cm-block { margin-top: 14px; }
.qr-completion .qr-cm-h { font-weight: 700; color: #003893; margin-bottom: 6px; }
.qr-completion ul { margin: 0; padding-left: 20px; color: #2a1f14; }
.qr-completion li { margin-bottom: 6px; line-height: 1.45; }
@media (max-width: 480px) {
  .qr-sim-container { padding: 16px; }
  .qr-sim-container .qr-sim-header { padding: 20px; }
  .qr-sim-container .qr-sim-kpi-value { font-size: 1.4rem; }
}
@media (prefers-reduced-motion: reduce) {
  .qr-sim-container *, .qr-completion * { transition: none !important; animation: none !important; }
  .qr-sim-container .qr-sim-kpi-card:hover { transform: none; }
}

