            var pairs = [
                ['onlinePctInput', 'onlinePctLabel'],
                ['weightIncomeInput', 'weightIncomeLabel'],
                ['intentionDiscountInput', 'intentionDiscountLabel'],
                ['growthAssumptionInput', 'growthLabel'],
                ['abastiaCaptureInput', 'captureLabel']
            ];
            pairs.forEach(function(p) {
                var input = document.getElementById(p[0]);
                var label = document.getElementById(p[1]);
                if (input && label) {
                    label.textContent = input.value;
                    if (input.dataset.qrLabelWired !== '1') {
                        input.addEventListener('input', function() { label.textContent = input.value; });
                        input.dataset.qrLabelWired = '1';
                    }
                }
            });
        }

        // ---- the study model -------------------------------------------------------------
        _design(n, f, q) {
            var w = WORDING[q] || WORDING.mixed;
            var share = POP_HIGH_INCOME + 10 * f;                      // high-income share in the sample
            return {
                n: n, f: f, q: q, qB: w.qB, qI: w.qI,
                cost: Math.round(n * (f * COST_ONLINE + (1 - f) * COST_F2F)),
                share: share,
                wStar: 100 * (1 - POP_HIGH_INCOME / share),             // down-weight that matches the population
                incomePart: 0.15 * f,                                   // coverage bias explained by income
                attitudePart: 0.15 * f,                                 // coverage bias no income weight can reach
                conv: CONVERSION / (1 + w.qI),
                followCost: Math.round(0.10 * n * COST_F2F),
                buyPct: Math.round(28.6 * (1 + 0.30 * f + w.qB)),
                intentPct: Math.round(37.9 * (1 + 0.30 * f) * (1 + w.qI))
            };
        }

        _analysis(r1, w, nr, disc) {
            var left = Math.max(0, BUDGET - r1.cost);
            var cov = 0, spend = 0;
            if (nr === 'followup') {
                cov = Math.max(0, Math.min(1, left / r1.followCost));
                spend = Math.round(Math.min(r1.followCost, left));
            }
            var nrRes = nr === 'none' ? 0.10 : (nr === 'reweight' ? 0.05 : 0.10 * (1 - 0.85 * cov));
            var incRes = r1.incomePart * (1 - w / r1.wStar);
            var dStar = 100 * (1 - r1.conv);
            var intRes = (1 - disc / 100) / r1.conv - 1;
            return {
                w: w, nr: nr, disc: disc, cov: cov, spend: spend, left: left,
                nrRes: nrRes, incRes: incRes, dStar: dStar, intRes: intRes,
                infA: 0.30 * r1.f + r1.qB + nrRes,
                infB: r1.attitudePart + incRes + r1.qB + nrRes
            };
        }

        _methods(r2) {
            var eA = r2.infA, eB = r2.infB, eC = (1 + r2.infB) * (1 + r2.intRes) - 1;
            return { A: eA, B: eB, C: eC };
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var cp = state.currentPeriod;
            var dc = 0, costRound = 0, codes = '';
            var bias = ds.biasIndex;

            if (cp === 1) {
                var r1 = this._design(parseInt(d.sampleSize, 10) || 1050, (parseInt(d.onlinePct, 10) || 50) / 100, d.neutralQ);
                ds.r1 = r1;
                costRound = r1.cost;
                dc += r1.n === 600 ? -4 : (r1.n === 1500 ? 4 : 3);
                dc += r1.f <= 0.3 ? 3 : (r1.f <= 0.5 ? 0 : (r1.f <= 0.7 ? -3 : -6));
                dc += r1.q === 'neutral' ? 4 : (r1.q === 'leading' ? -8 : -2);
                bias = 100 * Math.min(1, (0.30 * r1.f + r1.qB + 0.10 + 0.5 * r1.qI) / 0.6);
                codes = '1|' + r1.n + '|' + Math.round(r1.f * 100) + '|' + r1.q;
            } else if (cp === 2) {
                var a1 = ds.r1 || this._design(1050, 0.5, 'mixed');
                var r2 = this._analysis(a1, parseInt(d.weightIncome, 10) || 0, d.nonResponseAdj, parseInt(d.intentionDiscount, 10) || 0);
                ds.r2 = r2;
                costRound = r2.spend;
                if (r2.w === 0) dc -= 6;
                else if (Math.abs(r2.w - a1.wStar) <= 7.5) dc += 4;
                else dc += (r2.w < a1.wStar ? -1 : -3);
                if (r2.nr === 'followup') dc += r2.cov >= 0.999 ? 5 : (r2.cov > 0 ? 2 : -3);
                else dc += r2.nr === 'reweight' ? 2 : -6;
                if (r2.disc === 0) dc -= 6;
                else if (Math.abs(r2.disc - r2.dStar) <= 10) dc += 5;
                else dc += (r2.disc < r2.dStar ? 0 : -2);
                bias = 100 * Math.min(1, (Math.abs(r2.infB) + 0.25 * Math.abs(r2.intRes)) / 0.6);
                codes = '2|' + r2.w + '|' + r2.nr + '|' + r2.disc + '|' + Math.round(r2.cov * 100);
            } else if (cp === 3) {
                var b2 = ds.r2 || this._analysis(ds.r1 || this._design(1050, 0.5, 'mixed'), 0, 'none', 0);
                var m = this._methods(b2);
                var meth = (d.method === 'A' || d.method === 'C') ? d.method : 'B';
                var g = parseInt(d.growthAssumption, 10) || 15;
                var s = parseInt(d.abastiaCapture, 10) || 25;
                var err = m[meth];
                var est = Math.round(TRUE_MARKET * (1 + err));
                if (meth === 'A') dc -= 4;
                else if (meth === 'B') dc += b2.w >= 5 ? 5 : 0;
                else dc += Math.abs(b2.intRes) <= 0.10 ? 1 : -4;
                dc += (g >= 10 && g <= 20) ? 2 : (g > 25 ? -6 : (g > 20 ? -2 : (g < 8 ? -3 : 0)));
                dc += s <= 15 ? 3 : (s <= 20 ? 1 : (s <= 30 ? -3 : -8));
                ds.r3 = { method: meth, g: g, s: s, err: err, est: est, eA: m.A, eB: m.B, eC: m.C,
                          y3: Math.round(est * Math.pow(1 + g / 100, 3) * s / 100) };
                ds.marketEstimate = est;
                bias = 100 * Math.min(1, Math.abs(err) / 0.6);
                codes = '3|' + meth + '|' + g + '|' + s;
            } else if (cp === 4) {
                var e3 = ds.r3 ? Math.abs(ds.r3.err) : 0.3;
                var rec = d.recommend, conf = d.confidence, disc4 = d.disclosure;
                dc += rec === 'invest_partial' ? 5 : (rec === 'defer' ? 1 : (rec === 'reject' ? -4 : -6));
                dc += conf === 'balanced' ? 4 : (conf === 'cautious' ? (ds.biasIndex >= 40 ? 4 : 0) : (e3 < 0.05 ? -2 : -8));
                dc += disc4 === 'full' ? 5 : (disc4 === 'partial' ? 0 : -10);
                var recFit = rec === 'invest_partial' ? 1 : (rec === 'defer' ? 0.6 : (rec === 'reject' ? 0.3 : 0));
                var confFit = conf === 'balanced' ? 1 : (conf === 'cautious' ? (ds.biasIndex >= 40 ? 0.9 : 0.6) : (e3 < 0.05 ? 0.6 : 0.1));
                var discFit = disc4 === 'full' ? 1 : (disc4 === 'partial' ? 0.5 : 0);
                ds.r4 = { rec: rec, conf: conf, disc: disc4, decision: 0.6 * recFit + 0.2 * confFit + 0.2 * discFit };
                codes = '4|' + rec + '|' + conf + '|' + disc4;
            }

            ds.credibility = Math.max(0, Math.min(150, ds.credibility + dc));
            ds.biasIndex = Math.max(0, Math.min(100, bias));
            ds.budgetUsed += costRound;
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.biasHistory.push(Math.round(ds.biasIndex));
            ds.marketHistory.push(ds.marketEstimate);

            var sub = this._subScores(ds);
            var overallScore = this._computeScore(ds);
            ds.performance = { overallScore: overallScore, grade: this._letterGrade(overallScore),
                               outcome: sub.outcome, process: sub.process, decision: sub.decision };
            ds.performanceTier = this._tierFor(overallScore);

            return {
                period: cp,
                credibilityDelta: Math.round(dc * 10) / 10,
                credibility: Math.round(ds.credibility),
                biasIndex: Math.round(ds.biasIndex),
                marketEstimate: ds.marketEstimate,
                costRound: costRound,
                noteCodes: codes,
                notes: this._noteText(codes),
                overallScore: overallScore,
                score: overallScore,
                grade: ds.performance.grade
            };
        }

        // Sub-scores, each 0 to 100: outcome = accuracy of the estimate against the later sales,
        // process = methodological credibility, decision = the recommendation and how it was told.
        _subScores(ds) {
            var acc = ds.r3 ? Math.max(0, 1 - Math.abs(ds.r3.err) / 0.40) : null;
            return {
                outcome: acc == null ? null : Math.round(100 * acc),
                process: Math.round(100 * Math.max(0, Math.min(1, ds.credibility / 150))),
                decision: ds.r4 ? Math.round(100 * ds.r4.decision) : null,
                acc: acc
            };
        }

        _computeScore(ds) {
            var sub = this._subScores(ds);
            var cred = Math.max(0, Math.min(1, ds.credibility / 150));
            var score;
            if (ds.r4 && sub.acc != null) score = 100 * (0.45 * sub.acc + 0.35 * cred + 0.20 * ds.r4.decision);
            else if (sub.acc != null) score = 100 * (0.45 * sub.acc + 0.35 * cred) / 0.80;
            else score = 100 * (0.55 * cred + 0.45 * (1 - ds.biasIndex / 100));
            return Math.round(Math.max(0, Math.min(100, score)));
        }

        // One function maps the score to grade and tier, so label and score never disagree.
        _letterGrade(s) {
            return s >= 85 ? 'A' : s >= 70 ? 'B' : s >= 55 ? 'C' : s >= 40 ? 'D' : 'F';
        }

        _tierFor(s) {
            return s >= 85 ? 'excelente' : s >= 70 ? 'solido' : s >= 55 ? 'aceptable' : 'principiante';
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period,
                credibilityDelta: r.credibilityDelta,
                credibility: r.credibility,
                biasIndex: r.biasIndex,
                marketEstimate: r.marketEstimate,
                costRound: r.costRound,
                noteCodes: r.noteCodes,
                notes: r.notes,
                overallScore: r.overallScore,
                score: r.score,
                grade: r.grade
            };
        }

        // ---- text the adapter writes ------------------------------------------------------
        _noteText(codes) {
            if (!codes) return '';
            var p = String(codes).split('|');
            var t = (k) => window.mySimulation.t(k);
            if (p[0] === '1') return this._t('note_r1', { n: p[1], f: p[2], q: t('q_' + p[3]) });
            if (p[0] === '2') return this._t('note_r2', { w: p[1], nr: t('nr_' + p[2]), d: p[3] }) +
                (p[2] === 'followup' ? ' ' + this._t('note_cov', { c: p[4] }) : '');
            if (p[0] === '3') return this._t('note_r3', { m: p[1], g: p[2], s: p[3] });
            if (p[0] === '4') {
                var rk = { invest_full: 'rec_full', invest_partial: 'rec_partial', defer: 'rec_defer', reject: 'rec_reject' }[p[1]] || 'rec_partial';
                var ck = { high: 'conf_high', balanced: 'conf_balanced', cautious: 'conf_cautious' }[p[2]] || 'conf_balanced';
                var dk = { omit: 'disc_omit', partial: 'disc_partial', full: 'disc_full' }[p[3]] || 'disc_partial';
                return t(rk) + ' · ' + t(ck) + ' · ' + t(dk);
            }
            return '';
        }

        _briefingFor(cp, ds) {
            var t = (k, p) => this._t(k, p);
            if (cp === 2 && ds.r1) {
                var r1 = ds.r1;
                return t('round2_brief', {
                    n: r1.n, f: Math.round(r1.f * 100), buy: r1.buyPct, intent: r1.intentPct,
                    share: this._num(r1.share, 0), pop: POP_HIGH_INCOME, nr: NR_RATE,
                    fc: this._fmtM(r1.followCost), left: this._fmtM(Math.max(0, BUDGET - r1.cost))
                });
            }
            if (cp === 3 && ds.r2) {
                var m = this._methods(ds.r2);
                return t('round3_brief', {
                    a: this._fmtB(TRUE_MARKET * (1 + m.A)),
                    b: this._fmtB(TRUE_MARKET * (1 + m.B)),
                    c: this._fmtB(TRUE_MARKET * (1 + m.C))
                });
            }
            if (cp === 4 && ds.r3) {
                return t('round4_brief', { est: this._fmtB(ds.r3.est), g: ds.r3.g, s: ds.r3.s, y3: this._fmtB(ds.r3.y3) });
            }
            var key = this.ROUNDS[Math.min(Math.max(cp - 1, 0), 3)].briefingKey;
            return t(key + (cp > 1 ? '_generic' : ''));
        }

        _updateBriefing(state) {
            var cp = (state && state.currentPeriod) || 1;
            var idx = Math.min(Math.max(cp - 1, 0), this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var ds = (state && state.domainState) || {};

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) nameEl.textContent = window.mySimulation.t(round.nameKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._briefingFor(Math.min(cp, 4), ds);

            for (var i = 1; i <= 4; i++) {
                var p = document.getElementById('panelRound' + i);
                if (p) p.style.display = (i === cp) ? 'block' : 'none';
            }
            this._wireSliderLabels();
        }

        validateDecisions(decisions) {
            var cp = window.mySimulation.state.currentPeriod || 1;

            if (cp === 1) {
                var ss = document.getElementById('sampleSizeInput');
                var op = document.getElementById('onlinePctInput');
                var nq = document.getElementById('neutralQuestionsInput');
                if (ss) decisions.sampleSize = parseInt(ss.value);
                if (op) decisions.onlinePct = parseInt(op.value);
                if (nq) decisions.neutralQ = nq.value;

                var onlineFrac = decisions.onlinePct / 100;
                var totalCost = (onlineFrac * COST_ONLINE + (1 - onlineFrac) * COST_F2F) * decisions.sampleSize;
                if (totalCost > BUDGET * 1.05) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_warning'), 'warning'
                    );
                    return false;
                }
            } else if (cp === 2) {
                var wi = document.getElementById('weightIncomeInput');
                var nr = document.getElementById('nonResponseAdjInput');
                var id = document.getElementById('intentionDiscountInput');
                if (wi) decisions.weightIncome = parseInt(wi.value);
                if (nr) decisions.nonResponseAdj = nr.value;
                if (id) decisions.intentionDiscount = parseInt(id.value);
            } else if (cp === 3) {
                var m = document.getElementById('methodInput');
                var g = document.getElementById('growthAssumptionInput');
                var cc = document.getElementById('abastiaCaptureInput');
                if (m) decisions.method = m.value;
                if (g) decisions.growthAssumption = parseInt(g.value);
                if (cc) decisions.abastiaCapture = parseInt(cc.value);
            } else if (cp === 4) {
                var r = document.getElementById('recommendInput');
                var c = document.getElementById('confidenceInput');
                var d = document.getElementById('disclosureInput');
                if (r) decisions.recommend = r.value;
                if (c) decisions.confidence = c.value;
                if (d) decisions.disclosure = d.value;
            }
            return true;
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('credibilityDisplay', 'domainState.credibility',
                (v) => Math.round(v) + ' / 150');
            uiManager.bind('biasDisplay', 'domainState.biasIndex',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('marketDisplay', 'domainState.marketEstimate',
                (v) => v > 0 ? self._fmtB(v) : '—');
            uiManager.bind('budgetDisplay', 'domainState.budgetUsed',
                (v) => 'COP ' + self._num(v / 1000000, 0) + 'M');
        }

        getChartConfig() {
            var t = (k) => window.mySimulation.t(k);
            return {
                credibilityChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_cred_series'),
                            data: [],
                            borderColor: '#003893',
                            backgroundColor: 'rgba(0,56,147,0.12)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t('chart_cred_title') } },
                        scales: { y: { beginAtZero: true, max: 150 } }
                    }
                },
                biasChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_bias_series'),
                            data: [],
                            backgroundColor: 'rgba(193,39,45,0.7)',
                            borderColor: '#c1272d',
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t('chart_bias_title') } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var t = (k) => window.mySimulation.t(k);
            var ds = (state && state.domainState) || {};
            var cred = ds.credibilityHistory || [];
            var labels = cred.map((_, i) => 'R' + (i + 1));
            return {
                credibilityChart: {
                    labels: labels,
                    datasets: [{ label: t('chart_cred_series'), data: cred }]
                },
                biasChart: {
                    labels: labels,
                    datasets: [{ label: t('chart_bias_series'), data: ds.biasHistory || [] }]
                }
            };
        }

        // Hints point at the evidence on the table; they never name the option to pick.
        getHint(state, results) {
            if (!results) return null;
            var justPlayed = results.period || state.currentPeriod;
            if (justPlayed === 1) return window.mySimulation.t('hint_after_r1');
            if (justPlayed === 2) return window.mySimulation.t('hint_after_r2');
            if (justPlayed === 3) return window.mySimulation.t('hint_after_r3');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'period', label: 'Ronda', i18nKey: 'col_round' },
                { key: 'results.credibilityDelta', label: 'Δ Credibilidad', i18nKey: 'col_cred_delta' },
                { key: 'results.credibility', label: 'Credibilidad', i18nKey: 'col_credibility' },
                { key: 'results.biasIndex', label: 'Sesgo', i18nKey: 'col_bias' },
                { key: 'results.noteCodes', label: 'Notas', i18nKey: 'col_notes',
                  formatter: function(v) { return self._noteText(v); } }
            ];
        }

        getPresets() { return null; }

        // ---- debrief ----------------------------------------------------------------------
        _debriefCodes(ds) {
            var out = [];
            var r1 = ds.r1, r2 = ds.r2, r3 = ds.r3, r4 = ds.r4;
            if (!r1 || !r2 || !r3) return out;
            // contributions to the final estimate error, for the turning point
            var cov = r3.method === 'A' ? 0.30 * r1.f : (r1.attitudePart + r2.incRes);
            var parts = [
                { k: 'tp_coverage', v: Math.abs(cov), r: 1 },
                { k: 'tp_wording', v: Math.abs(r1.qB) + (r3.method === 'C' ? r1.qI : 0), r: 1 },
                { k: 'tp_nonresponse', v: Math.abs(r2.nrRes), r: 2 },
                { k: 'tp_intention', v: r3.method === 'C' ? Math.abs(r2.intRes) : 0, r: 3 },
                { k: 'tp_weighting', v: r3.method !== 'A' && r2.w > r1.wStar + 7.5 ? Math.abs(r2.incRes) : 0, r: 2 }
            ];
            if (r4) parts.push({ k: 'tp_presentation', v: r4.decision < 0.5 ? 0.6 - r4.decision : 0, r: 4 });
            parts.sort(function(a, b) { return b.v - a.v; });
            out.push({ k: 'ins_outcome', p: { truth: 'TRUTH', est: 'EST', err: 'ERR' } });
            if (parts[0].v >= 0.04) out.push({ k: parts[0].k, p: { r: parts[0].r } });
            else out.push({ k: 'tp_none' });
            if (r1.f >= 0.6) out.push({ k: 'ins_m_online', p: { f: Math.round(r1.f * 100) } });
            if (r1.q === 'leading') out.push({ k: 'ins_m_leading' });
            if (r3.method === 'C' && r2.disc < r2.dStar - 10) out.push({ k: 'ins_m_intention', p: { d: r2.disc, ds: Math.round(r2.dStar) } });
            if (r3.method === 'A') out.push({ k: 'ins_m_direct' });
            if (r2.nr === 'none') out.push({ k: 'ins_m_nonresponse' });
            if (r2.nr === 'followup' && r2.cov < 0.999) out.push({ k: 'ins_m_nofunds', p: { c: Math.round(r2.cov * 100) } });
            if (r2.w === 0 && r3.method !== 'A') out.push({ k: 'ins_m_noweight', p: { ws: Math.round(r1.wStar) } });
            if (r2.w > r1.wStar + 7.5 && r3.method !== 'A') out.push({ k: 'ins_m_overweight', p: { w: r2.w, ws: Math.round(r1.wStar) } });
            if (r3.g > 20 || r3.s > 20) out.push({ k: 'ins_m_assumptions', p: { g: r3.g, s: r3.s } });
            if (r4 && r4.rec === 'invest_full' && (r4.conf === 'high' || r4.disc === 'omit')) out.push({ k: 'ins_m_client' });
            else if (r4 && r4.disc === 'omit') out.push({ k: 'ins_m_omit' });
            else if (r4 && r4.rec === 'invest_full') out.push({ k: 'ins_m_full' });
            if (out.length < 3) {
                if (Math.abs(r3.err) <= 0.08) out.push({ k: 'ins_g_close' });
                if (r4 && r4.disc === 'full' && r4.conf !== 'high') out.push({ k: 'ins_g_transparent' });
                if (r2.nr === 'followup' && r2.cov >= 0.999) out.push({ k: 'ins_g_followup' });
            }
            return out.slice(0, 5);
        }

        _renderCode(c, ds) {
            var p = Object.assign({}, c.p || {});
            if (c.k === 'ins_outcome') {
                p.truth = this._fmtB(TRUE_MARKET);
                p.est = this._fmtB(ds.r3 ? ds.r3.est : 0);
                p.err = this._pct(ds.r3 ? ds.r3.err : 0);
            }
            return this._t(c.k, p);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var final = last.results || {};
            var ds = last.domainState || {};
            var credibility = final.credibility != null ? final.credibility : (ds.credibility || 0);
            var bias = final.biasIndex != null ? final.biasIndex : (ds.biasIndex || 0);
            var market = final.marketEstimate != null ? final.marketEstimate : (ds.marketEstimate || 0);
            var overallScore = (ds.performance && ds.performance.overallScore != null)
                ? ds.performance.overallScore : this._computeScore(ds);
            var grade = this._letterGrade(overallScore);
            var tier = this._tierFor(overallScore);
            var codes = this._debriefCodes(ds);
            var self = this;
            var sub = this._subScores(ds);
            return {
                overallScore: overallScore,
                totalScore: overallScore,
                score: overallScore,
                grade: grade,
                credibility: credibility,
                biasIndex: bias,
                marketEstimate: market,
                performanceTier: tier,
                performance: tier,
                performanceLabel: window.mySimulation.t('perf_' + tier),
                outcomeScore: sub.outcome,
                processScore: sub.process,
                decisionScore: sub.decision,
                insightCodes: codes,
                insights: codes.map(function(c) { return self._renderCode(c, ds); }),
                totalPeriods: history.length,
                _ds: ds
            };
        }

        formatCompletionMessage(summary) {
            var t = (k) => window.mySimulation.t(k);
            var self = this;
            summary = summary || {};
            var ds = summary._ds || {};
            var market = summary.marketEstimate || 0;
            var codes = Array.isArray(summary.insightCodes) ? summary.insightCodes : [];
            var insights = codes.length ? codes.map(function(c) { return self._renderCode(c, ds); })
                                        : (Array.isArray(summary.insights) ? summary.insights : []);
            var tier = summary.performanceTier || self._tierFor(summary.overallScore || 0);
            var row = function(label, val) {
                return '<div class="qr-cm-row"><span class="qr-cm-k">' + label + '</span>' +
                    '<span class="qr-cm-v">' + val + '</span></div>';
            };
            var sc = function(v) { return v == null ? '—' : (v + ' / 100'); };
            var rows = '';
            rows += row(t('score_label'), (summary.overallScore != null ? summary.overallScore : 0) + ' / 100 (' + (summary.grade || '—') + ')');
            rows += row(t('perf_label'), t('perf_' + tier));
            rows += row(t('sub_outcome'), sc(summary.outcomeScore));
            rows += row(t('sub_process'), sc(summary.processScore));
            rows += row(t('sub_decision'), sc(summary.decisionScore));
            rows += row(t('credibility_label'), Math.round(summary.credibility || 0) + ' / 150');
            rows += row(t('bias_label'), Math.round(summary.biasIndex || 0) + ' / 100');
            rows += row(t('market_label'), market > 0 ? self._fmtB(market) : '—');

            var list = function(title, items) {
                if (!items.length) return '';
                return '<div class="qr-cm-block"><div class="qr-cm-h">' + title + '</div><ul>' +
                    items.map(function(i) { return '<li>' + i + '</li>'; }).join('') + '</ul></div>';
            };
            var questions = [t('dq_1'), t('dq_2'), t('dq_3')];

            return '<div class="qr-completion" role="status" aria-live="polite">' +
                '<p class="qr-cm-title">' + t('completion_headline') + '</p>' +
                '<div class="qr-cm-rows">' + rows + '</div>' +
                list(t('insights_label'), insights) +
                list(t('questions_label'), questions) +
                '</div>';
        }

